// @ts-nocheck
import {
  buildCoreDeck,
  createAdaptiveProbabilityState,
  dealAdaptiveOpeningHands,
  isImmediateInteractionKind,
  selectAdaptiveDrawCard,
} from '../../../packages/game-engine/src/index.ts';

const BOT_NAMES = ['Maya','Leo','Nina','Jordan','Sam','Alex','Zoe','Arjun','Dev'];
const COLORS = ['lime','orange','cyan','purple'];
const COLOR_LABEL = { lime:'Acid Lime', orange:'Volt Orange', cyan:'Ice Cyan', purple:'Plasma Purple' };
const TURN_MS = 40000;
const SOCIAL_MS = 45000;
const PASS_DRAW = 2;

const PROMPTS = {
  truth: {
    clean: ['What harmless opinion do you defend too strongly?','What is something your friends would be surprised to learn about you?','What tiny skill are you unexpectedly proud of?'],
    adult: ['What assumption does this group have about you that is completely wrong?','What is a message you drafted and never sent?','What part of your reputation is most misunderstood?'],
  },
  dare: {
    clean: ['Act like a cartoon villain for 20 seconds.','Give a ten-second weather report about the mood in this room.','Hold the weirdest heroic pose you can invent until the next player begins.'],
    adult: ['Let the group choose a harmless nickname you answer to until your next turn.','Do your best celebrity impression for 20 seconds.','Deliver a dramatic acceptance speech for an award the group invents.'],
  },
  paranoia: {
    clean: ['Who here do you trust the least with a secret?','Who here tries hardest to look innocent?','Who here would you least want reading your private messages?'],
    adult: ['Who here do you secretly find the most annoying?','Who here would you never date even if they asked?','Who here do you think tries too hard to be liked?','Who here would you trust the least with something deeply personal?'],
  },
  duel: {
    clean: ['Name as many African countries as you can before the timer ends.','Make the best case for why you should control the music for the next hour.'],
    adult: ['Convince the room that you are the better liar.','Argue who would survive longer in a disaster. The room votes.'],
  },
};

const CHAOS_EFFECTS = [
  { id:'blind-swap', title:'Blind Swap', copy:'Everyone simultaneously gives 3 random cards face-down to the player on their left.' },
  { id:'reverse-order', title:'Reverse Order', copy:'Turn order reverses until the next Chaos begins.' },
];

const MACHIAVELLI = [
  ['convert-weak','Convert the Weak','Every existing Skip in hands, draw pool and discard becomes Draw +2.'],
  ['taboo-all','Taboo for All','Generate one Taboo directly into every player hand.'],
  ['no-mercy','No Mercy','Permanently remove every Nope from hands, draw pool and discard.'],
  ['paranoia-spreads','Paranoia Spreads','Each player gets one generated DIG ME or Paranoia.'],
  ['double-pressure','Double the Pressure','Duplicate every remaining drawable Truth and Dare.'],
  ['reverse-confession-all','Reverse Confession','Generate one Reverse Confession directly into every player hand.'],
];

const state = { session:null, flow:null, events:[], revision:0, botTimer:null, tick:null, active:false };
const $ = (s,r=document) => r.querySelector(s);
const $$ = (s,r=document) => Array.from(r.querySelectorAll(s));
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
const mod = (v,n) => ((v%n)+n)%n;
const uid = p => `${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
function seedNumber(text){ let h=2166136261; for(const c of String(text)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);} return h>>>0; }
function rng(seed){ let x=seedNumber(seed)||1; return { next(){x^=x<<13;x^=x>>>17;x^=x<<5;return (x>>>0)/4294967296;} }; }
function pick(list,seed){ return list.length ? list[Math.floor(rng(seed).next()*list.length)%list.length] : null; }
function shuffle(list,seed){ const out=[...list],r=rng(seed); for(let i=out.length-1;i>0;i--){const j=Math.floor(r.next()*(i+1));[out[i],out[j]]=[out[j],out[i]];} return out; }
function label(kind){ return String(kind).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()); }
function symbol(card){ return card.kind==='number' ? String(card.value) : card.kind; }
function player(id){ return state.session?.players.find(p=>p.id===id) ?? null; }
function current(){ return state.session?.players[state.session.currentIndex] ?? null; }
function human(){ return state.session?.players.find(p=>p.isHuman) ?? null; }
function indexOf(id){ return state.session?.players.findIndex(p=>p.id===id) ?? -1; }
function nextIndex(from=state.session.currentIndex,steps=1){ return mod(from+state.session.direction*steps,state.session.players.length); }
function top(){ return state.session?.discard.at(-1) ?? null; }
function cardSymbol(card){ return card.kind==='number' ? String(card.value) : card.kind; }
function familyLabel(kind){ return String(kind).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()); }
function event(type,message){ state.events.unshift({type,message,time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}); state.events=state.events.slice(0,60); }
function toast(title,copy){ const n=document.createElement('div');n.style.cssText='position:fixed;right:18px;bottom:18px;z-index:99999;background:#111827;color:#fff;padding:12px 14px;border-radius:12px;max-width:330px;box-shadow:0 10px 30px #0008';n.innerHTML=`<b>${esc(title)}</b><div style="margin-top:4px;font-size:12px">${esc(copy)}</div>`;document.body.append(n);setTimeout(()=>n.remove(),2600); }
function showGame(){ $$('.view').forEach(v=>v.classList.toggle('is-active',v.dataset.view==='game'));document.body.classList.add('is-game-view');window.scrollTo(0,0); }

function makePlayers(count,name){ return Array.from({length:count},(_,i)=>({id:`p${i}`,seat:i,name:i===0?name:(BOT_NAMES[i-1]??`Player ${i+1}`),isHuman:i===0,hand:[],rewind:true,ghostArmed:null,ghostTurns:0,stats:{draws:0,played:0,nope:0}})); }
function generated(kind,extra={}){ return {id:uid(`gen-${kind}`),kind,symbol:kind,...extra}; }
function startGame(){
  const count=Math.max(2,Math.min(10,Number($('#playerCount')?.value||5)));
  const name=String($('#profileName')?.value||'You').trim()||'You';
  const room=String($('#roomName')?.value||'Night Squad').trim()||'Night Squad';
  const world=$('#worldSelect')?.value==='adult'?'adult':'clean';
  const seed=`${Date.now()}-${Math.random()}`;
  const players=makePlayers(count,name);
  const physical=buildCoreDeck(seed);
  const starterIndex=physical.findIndex(c=>c.kind==='number');
  const starter=physical.splice(starterIndex,1)[0];
  const deal=dealAdaptiveOpeningHands(physical,count,7,rng(`${seed}:opening`));
  players.forEach((p,i)=>{p.hand=deal.hands[i]??[];});
  state.session={id:uid('session'),room,world,seed,players,deck:deal.remainingDeck,discard:[starter],exhausted:[],currentIndex:0,direction:1,activeColor:starter.color??null,activeSymbol:symbol(starter),phase:'PLAY_DRAW',winnerId:null,completedTurns:0,round:1,adaptiveProbability:createAdaptiveProbabilityState(),chaosReverse:false,actionStack:[],deadline:Date.now()+TURN_MS};
  state.flow=null;state.events=[];state.revision++;state.active=true;
  event('CANONICAL GAME STARTED',`${room}: ${count} players, exactly 7 cards each, CHAOS-133-V1.`);
  event('CHAOS PULSE ACTIVE','Opening distribution and every post-start physical draw use the shared adaptive physical-card selector.');
  showGame();beginTurn();render();
}

function adapter(){ const s=state.session; return {drawPile:s.deck,discardPile:s.discard,config:{seed:s.seed},revision:state.revision,adaptiveProbability:s.adaptiveProbability}; }
function recycle(){ const s=state.session;if(!s||s.discard.length<=1)return false;const active=s.discard.pop();const cards=s.discard.splice(0);s.deck.push(...shuffle(cards,`${s.seed}:recycle:${state.revision}`));s.discard=[active];event('DECK RECYCLED','Reusable discard cards returned to the physical draw pool.');return true; }
function drawOne(){ const s=state.session;if(!s.deck.length&&!recycle())throw new Error('No cards available.');const a=adapter();const card=selectAdaptiveDrawCard(a);s.adaptiveProbability=a.adaptiveProbability;if(!card)throw new Error('No card selected.');return card; }
function putDiscard(card){ const s=state.session;s.discard.push(card);if(card.color)s.activeColor=card.color;s.activeSymbol=cardSymbol(card); }
function exhaust(card){ const s=state.session;if(!card)return;const i=s.discard.findIndex(c=>c.id===card.id);if(i>=0)s.exhausted.push(s.discard.splice(i,1)[0]);else if(!s.exhausted.some(c=>c.id===card.id))s.exhausted.push(card); }
function physicalDraw(p,count,done){ const forced=[];for(let i=0;i<count;i++){const card=drawOne();p.stats.draws++;if(isImmediateInteractionKind(card.kind))forced.push(card);else p.hand.push(card);}event('CARD DRAWN',`${p.name} drew ${count} physical card${count===1?'':'s'}.`);runForced(p,forced,done); }
function runForced(p,queue,done){ const card=queue.shift();if(!card){done?.();render();return;}putDiscard(card);event('FORCED CARD TRIGGERED',`${p.name} drew ${familyLabel(card.kind)}; it auto-triggered immediately.`);trigger(card,p,()=>{exhaust(card);runForced(p,queue,done);},true); }

function beginTurn(){ const s=state.session;if(!s||s.winnerId)return;const p=current();s.phase='PLAY_DRAW';s.deadline=Date.now()+TURN_MS;event('TURN START',`${p.name} is active.`);render();scheduleBot(); }
function confirmWin(p){ if(!p||p.hand.length!==0)return false;const s=state.session;s.winnerId=p.id;s.phase='FINISHED';s.deadline=null;state.flow=null;clearTimeout(state.botTimer);event('WINNER',`${p.name} legally emptied their hand after the full effect-resolution boundary.`);render();return true; }
function finishTurn(actor,steps=1){
  const s=state.session;if(!s||s.winnerId)return;
  if(actor?.ghostTurns>0){actor.ghostTurns--;if(actor.ghostTurns===0)event('GHOST ENDED',`${actor.name} is no longer a Ghost.`);}
  const frame=s.actionStack.at(-1);
  if(frame&&frame.playerId===actor?.id){
    s.actionStack.pop();
    if(frame.card)exhaust(frame.card);
    if(frame.pendingWinnerId){const pending=player(frame.pendingWinnerId);if(pending?.hand.length===0&&confirmWin(pending))return;}
    if(frame.afterAction){frame.afterAction();return;}
    if(frame.kind==='tag'){s.currentIndex=frame.returnIndex;beginTurn();return;}
    if(frame.kind==='hijack'){s.currentIndex=nextIndex(s.currentIndex,1);beginTurn();return;}
  }
  if(confirmWin(actor))return;
  s.completedTurns++;s.currentIndex=nextIndex(s.currentIndex,steps);if(s.currentIndex===0)s.round++;beginTurn();
}
function legal(card,p){ const s=state.session;if(!s||!p||p.id!==current()?.id||s.phase!=='PLAY_DRAW'||state.flow)return false;if(card.kind==='nope')return false;if(card.kind==='wild'||card.kind==='ghost')return true;if(isImmediateInteractionKind(card.kind)){if(card.kind==='tag'&&s.actionStack.some(f=>f.kind==='tag'))return false;return true;}if(card.color&&card.color===s.activeColor)return true;return cardSymbol(card)===s.activeSymbol; }
function playCard(id){
  const s=state.session,a=current();if(!s||!a||state.flow||s.phase!=='PLAY_DRAW')return;const i=a.hand.findIndex(c=>c.id===id);if(i<0)return;const card=a.hand[i];if(!legal(card,a))return toast('Illegal card','That card is not legal now.');a.hand.splice(i,1);a.stats.played++;s.phase='TRIGGER';
  if(card.kind==='ghost'){a.ghostArmed=card;event('GHOST ARMED',`${a.name} played Ghost face-down. Activate it on a later personal turn.`);return finishTurn(a);}
  putDiscard(card);event('CARD PLAYED',`${a.name} played ${familyLabel(card.kind)}.`);
  if(card.kind==='number')return finishTurn(a);
  if(card.kind==='skip')return finishTurn(a,2);
  if(card.kind==='reverse'){s.direction*=-1;event('REVERSE',`Direction is now ${s.direction===1?'clockwise':'counterclockwise'}.`);return finishTurn(a,s.players.length===2?2:1);}
  if(card.kind==='draw'){const target=s.players[nextIndex()];physicalDraw(target,2,()=>finishTurn(a));return;}
  if(card.kind==='wild'){state.flow={kind:'wild',actorId:a.id,card,step:'wild',done:()=>finishTurn(a),deadline:Date.now()+SOCIAL_MS};s.phase='ANSWER_RESOLVE';render();return;}
  if(isImmediateInteractionKind(card.kind))trigger(card,a,()=>{exhaust(card);finishTurn(a);},false);
}
function drawTurn(){const s=state.session,a=current();if(!s||!a||state.flow||s.phase!=='PLAY_DRAW')return;if(a.ghostTurns>0)return toast('Ghost turn','Ghosts do not take the normal draw.');if(a.hand.some(c=>legal(c,a)))return toast('Legal card available','Normal draw is unavailable while you hold a legal play.');s.phase='TRIGGER';physicalDraw(a,1,()=>finishTurn(a));}

function baseFlow(card,a,done,forced){return{card,actorId:a.id,done,forced,resolved:false,deadline:Date.now()+SOCIAL_MS};}
function trigger(card,a,done,forced){
  const b=baseFlow(card,a,done,forced),s=state.session;s.phase='ANSWER_RESOLVE';
  if(card.kind==='truth')state.flow={...b,kind:'truth',targetId:a.id,step:'source',source:null,prompt:null};
  else if(card.kind==='dare')state.flow={...b,kind:'dare',targetId:null,step:'target',source:null,prompt:null};
  else if(card.kind==='paranoia')state.flow={...b,kind:'paranoia',targetId:null,answerId:null,branch:null,step:'source',source:null,prompt:null,votes:{}};
  else if(card.kind==='duel')state.flow={...b,kind:'duel',opponentId:null,step:'target',source:null,prompt:null,timer:30,responses:{},votes:{}};
  else if(card.kind==='chaos')beginChaos(b);
  else if(card.kind==='tag')state.flow={...b,kind:'tag',step:'target',targetId:null};
  else if(card.kind==='hijack')state.flow={...b,kind:'hijack',step:'target',targetId:null};
  else if(card.kind==='taboo')state.flow={...b,kind:'taboo',step:'target',targetId:null,question:''};
  else if(card.kind==='truth_or_chaos')state.flow={...b,kind:'truth_or_chaos',step:'question',targetIds:s.players.filter(p=>p.id!==a.id).map(p=>p.id),question:'',options:['YES','NO'],answers:{},groupDare:'',completions:{}};
  else if(card.kind==='machiavelli')state.flow={...b,kind:'machiavelli',step:'choice'};
  else if(card.kind==='reverse_confession')state.flow={...b,kind:'reverse_confession',step:a.isHuman?'confess':'resolved',outcome:a.isHuman?'':`${a.name} completed a Reverse Confession live; content was not captured.`};
  else if(card.kind==='dig_me')state.flow={...b,kind:'dig_me',step:'target',targetId:null,question:'',live:false};
  if(state.flow?.step==='resolved')resolve(state.flow,state.flow.outcome);
  render();autoBots();
}
function resolve(f,outcome='Effect resolved.'){f.resolved=true;f.step='resolved';f.outcome=outcome;f.deadline=null;render();if(!player(f.actorId)?.isHuman&&!needsHuman(f))setTimeout(completeFlow,200);}
function completeFlow(){const f=state.flow;if(!f?.resolved)return;state.flow=null;state.revision++;f.done?.();render();}
function needsHuman(f){
  const h=human();
  if(!h)return false;
  if(f.kind==='taboo'){
    if(f.step==='target'||f.step==='taboo-question')return f.actorId===h.id;
    if(f.step==='taboo-answer')return f.targetId===h.id;
    if(f.step==='resolved')return f.actorId===h.id||f.targetId===h.id;
  }
  return[f.actorId,f.targetId,f.opponentId,f.answerId].includes(h.id)||f.targetIds?.includes(h.id);
}
function promptFor(kind,actorId){const list=PROMPTS[kind]?.[state.session.world]??[];return pick(list,`${state.session.seed}:${state.revision}:${kind}:${actorId}`);}
function chooseSource(source){const f=state.flow;if(!f||!['truth','dare','paranoia','duel'].includes(f.kind)||f.step!=='source')return;f.source=source;if(source==='roulette'){f.prompt=promptFor(f.kind,f.actorId);f.step='preview';event('PROMPT PRESELECTED',`The ${f.kind} Roulette result was selected authoritatively before presentation.`);}else f.step='manual';render();autoBots();}
function manualPrompt(text){const f=state.flow,v=String(text||'').trim();if(!f||f.step!=='manual')return;if(v.length<10||v.length>280)return toast('Prompt length','Write 10-280 characters.');f.prompt=v;f.step='preview';render();autoBots();}
function selectDareTarget(id){const f=state.flow;if(!f||f.kind!=='dare'||f.step!=='target'||id===f.actorId||!player(id))return;f.targetId=id;f.step='source';event('DARE TARGET',`${player(f.actorId).name} targeted ${player(id).name} before prompt selection.`);render();autoBots();}
function publish(){const f=state.flow;if(!f||f.step!=='preview')return;if(f.kind==='paranoia')f.step='paranoia-target';else if(f.kind==='duel')f.step='duel-timer';else f.step='response';event('PROMPT REVEALED',`${player(f.targetId||f.actorId)?.name} received the public ${f.kind} prompt.`);render();autoBots();}
function rewind(){const f=state.flow,t=player(f?.targetId||f?.actorId);if(!f||!['truth','dare'].includes(f.kind)||f.step!=='preview'||f.source!=='roulette'||!t?.rewind)return;const list=PROMPTS[f.kind][state.session.world].filter(x=>x!==f.prompt);if(!list.length)return;f.prompt=pick(list,`${state.session.seed}:rewind:${state.revision}:${t.id}`);t.rewind=false;event('PROMPT REWOUND',`${t.name} privately replaced the Roulette prompt.`);render();}
function nope(){const f=state.flow;if(!f||!['truth','dare'].includes(f.kind)||!['preview','response'].includes(f.step))return;const t=player(f.targetId||f.actorId),i=t?.hand.findIndex(c=>c.kind==='nope')??-1;if(i<0)return toast('No Nope','The affected player does not hold a Nope.');const [card]=t.hand.splice(i,1);state.session.exhausted.push(card);t.stats.nope++;event('NOPE',`${t.name} used Nope and the ${familyLabel(f.kind)} challenge vanished with no refusal penalty.`);resolve(f,`${t.name} played Nope. The challenge is cancelled.`);}
function pass(){const f=state.flow;if(!f)return;if(['truth','dare'].includes(f.kind)){const t=player(f.targetId||f.actorId),parent=f;event('PASS',`${t.name} chose Pass / Not for Me and draws 2 before resolution.`);physicalDraw(t,PASS_DRAW,()=>{state.flow=parent;resolve(parent,`${t.name} passed and drew 2.`);});return;}if(f.kind==='paranoia'&&['source','manual','preview','paranoia-target'].includes(f.step))return resolve(f,'Paranoia was passed before target resolution.');if(f.kind==='duel')return resolve(f,'Duel was passed. No winner is invented.');if(f.kind==='truth_or_chaos'&&f.step==='group-complete'){const h=human();if(f.targetIds.includes(h.id)){f.completions[h.id]='PASS';finishGroup(f);}}}
function truthAnswer(live=false){const f=state.flow;if(!f||f.kind!=='truth'||f.step!=='response')return;const v=String($('#canonicalTruth')?.value||'').trim();if(!live&&!v)return toast('Answer required','Type an answer or choose Answered Live.');event('TRUTH ANSWERED',`${player(f.targetId).name} answered${live?' live; content was not captured':''}.`);resolve(f,'Truth answered.');}
function dareDone(){const f=state.flow;if(!f||f.kind!=='dare'||f.step!=='response')return;event('DARE COMPLETED',`${player(f.targetId).name} completed the Dare.`);resolve(f,'Dare completed.');}

function paranoiaTarget(id){const f=state.flow;if(!f||f.kind!=='paranoia'||f.step!=='paranoia-target'||id===f.actorId)return;f.targetId=id;f.step='paranoia-branch';render();autoBots();}
function paranoiaBranch(branch){const f=state.flow;if(!f||f.kind!=='paranoia'||f.step!=='paranoia-branch')return;f.branch=branch;f.step=branch==='classic'?'paranoia-answer-player':'paranoia-target-answer';render();autoBots();}
function paranoiaAnswerPlayer(id){const f=state.flow;if(!f||f.kind!=='paranoia'||f.step!=='paranoia-answer-player'||id===f.targetId)return;f.answerId=id;f.step='paranoia-decision';render();autoBots();}
function paranoiaDecision(choice,explicit=true){const f=state.flow;if(!f||f.kind!=='paranoia'||f.step!=='paranoia-decision')return;const a=player(f.answerId);if(choice==='reveal'){event('PARANOIA REVEALED',`${a.name} revealed: ${f.prompt}`);return resolve(f,`${a.name} chose Reveal.`);}if(!explicit)return resolve(f,'Classic Paranoia timed out. Privacy fallback kept the question secret with no voluntary Draw 1.');const parent=f;physicalDraw(a,1,()=>{state.flow=parent;event('KEEP SECRET DRAW',`${a.name} chose Keep Secret and drew 1.`);resolve(parent,`${a.name} chose Keep Secret and drew 1.`);});}
function paranoiaAnswered(){const f=state.flow;if(!f||f.kind!=='paranoia'||f.step!=='paranoia-target-answer')return;f.step='paranoia-vote';f.votes={};autoBots();render();}
function paranoiaVote(vote){const f=state.flow,h=human();if(!f||f.kind!=='paranoia'||f.step!=='paranoia-vote'||h.id===f.targetId||f.votes[h.id])return;f.votes[h.id]=vote;finishParanoiaVote(f);}
function finishParanoiaVote(f){const eligible=state.session.players.filter(p=>p.id!==f.targetId);if(!eligible.every(p=>f.votes[p.id]))return render();const b=Object.values(f.votes).filter(v=>v==='BELIEVE').length,l=Object.values(f.votes).filter(v=>v==='LYING').length;if(l>b){const t=player(f.targetId),parent=f;physicalDraw(t,2,()=>{state.flow=parent;resolve(parent,`${t.name} drew 2 after a strict Lying / Holding Back majority.`);});}else resolve(f,`${player(f.targetId).name} receives no Stranger penalty.`);}

function duelTarget(id){const f=state.flow;if(!f||f.kind!=='duel'||f.step!=='target'||id===f.actorId)return;f.opponentId=id;f.step='source';render();autoBots();}
function duelTimer(seconds){const f=state.flow;if(!f||f.kind!=='duel'||f.step!=='duel-timer')return;f.timer=[15,30,45].includes(Number(seconds))?Number(seconds):30;f.step='duel-challenger';f.deadline=Date.now()+f.timer*1000;render();autoBots();}
function duelResponse(side){const f=state.flow;if(!f||f.kind!=='duel')return;if(side==='challenger'&&f.step==='duel-challenger'){f.responses[f.actorId]=true;f.step='duel-opponent';}else if(side==='opponent'&&f.step==='duel-opponent'){f.responses[f.opponentId]=true;f.step='duel-vote';f.votes={};const eligible=state.session.players.filter(p=>p.id!==f.actorId&&p.id!==f.opponentId);if(!eligible.length)return resolve(f,'Two-player Duel has no eligible group voters, so no Duel winner is awarded.');}render();autoBots();}
function duelVote(id){const f=state.flow,h=human();if(!f||f.kind!=='duel'||f.step!=='duel-vote'||[f.actorId,f.opponentId].includes(h.id)||f.votes[h.id]||![f.actorId,f.opponentId].includes(id))return;f.votes[h.id]=id;finishDuelVote(f);}
function finishDuelVote(f){const e=state.session.players.filter(p=>p.id!==f.actorId&&p.id!==f.opponentId);if(!e.every(p=>f.votes[p.id]))return render();const a=e.filter(p=>f.votes[p.id]===f.actorId).length,b=e.length-a;if(a===b)return resolve(f,'Duel vote tied. No Duel winner is awarded.');const w=player(a>b?f.actorId:f.opponentId);event('DUEL RESULT',`${w.name} won the group vote. Game victory remains separate.`);resolve(f,`${w.name} won the Duel vote.`);}

function beginChaos(b){const s=state.session;if(s.chaosReverse){s.direction*=-1;s.chaosReverse=false;event('CHAOS REVERSE EXPIRED','The previous Reverse Order modifier expired as the next Chaos began.');}const effect=pick(CHAOS_EFFECTS,`${s.seed}:chaos:${state.revision}:${s.completedTurns}`);state.flow={...b,kind:'chaos',effect,step:'chaos'};}
function chaosResolve(){const f=state.flow,s=state.session;if(!f||f.kind!=='chaos'||f.step!=='chaos')return;if(f.effect.id==='reverse-order'){s.direction*=-1;s.chaosReverse=true;event('CHAOS REVERSE ORDER','Turn order reversed until the next Chaos begins.');return resolve(f,'Reverse Order is active until the next Chaos.');}const outgoing=new Map();s.players.forEach(p=>outgoing.set(p.id,shuffle(p.hand,`${s.seed}:blind:${state.revision}:${p.id}`).slice(0,Math.min(3,p.hand.length))));s.players.forEach(p=>{const ids=new Set(outgoing.get(p.id).map(c=>c.id));p.hand=p.hand.filter(c=>!ids.has(c.id));});s.players.forEach((p,i)=>s.players[mod(i+1,s.players.length)].hand.push(...outgoing.get(p.id)));event('BLIND SWAP','Blind Swap committed simultaneously around the table. Transfers were not treated as draws.');resolve(f,'Blind Swap completed.');}
function tagTarget(id){const f=state.flow,s=state.session;if(!f||f.kind!=='tag'||f.step!=='target'||id===f.actorId)return;const a=player(f.actorId),t=player(id),actorIndex=indexOf(a.id),returnIndex=nextIndex(actorIndex,1);state.flow=null;s.actionStack.push({kind:'tag',playerId:t.id,returnIndex,pendingWinnerId:a.hand.length===0?a.id:null,afterAction:f.forced?f.done:null,card:f.card});s.currentIndex=indexOf(t.id);event('TAG ALONG',`${t.name} gets one bonus Play-or-Draw action and keeps their regular turn later.`);beginTurn();}
function hijackTarget(id){const f=state.flow,s=state.session;if(!f||f.kind!=='hijack'||f.step!=='target'||id===f.actorId)return;const a=player(f.actorId),t=player(id),ai=indexOf(a.id),ti=indexOf(t.id);[s.players[ai],s.players[ti]]=[s.players[ti],s.players[ai]];s.players.forEach((p,i)=>p.seat=i);s.currentIndex=ai;state.flow=null;event('HIJACK',`${a.name} and ${t.name} permanently swapped rotation positions. ${t.name} draws 1 and takes over this position.`);physicalDraw(t,1,()=>{s.actionStack.push({kind:'hijack',playerId:t.id,pendingWinnerId:a.hand.length===0?a.id:null,afterAction:f.forced?f.done:null,card:f.card});beginTurn();});}
function tabooTarget(id){const f=state.flow;if(!f||f.kind!=='taboo'||f.step!=='target'||id===f.actorId)return;f.targetId=id;f.step='taboo-question';render();autoBots();}
function submitTabooQuestion(value){
  const f=state.flow,v=String(value||'').trim();
  if(!f||f.kind!=='taboo'||f.step!=='taboo-question')return false;
  if(v.length<3){if(player(f.actorId)?.isHuman)toast('Question required','Write the Taboo question before asking it.');return false;}
  f.question=v;
  f.step='taboo-answer';
  event('TABOO QUESTION',`${player(f.actorId).name} asked ${player(f.targetId).name} a Taboo question.`);
  render();
  autoBots();
  return true;
}
function tabooQuestion(){return submitTabooQuestion($('#canonicalTaboo')?.value);}
function tabooAnswer(yes){const f=state.flow;if(!f||f.kind!=='taboo'||f.step!=='taboo-answer')return;const t=player(f.targetId);if(yes)return resolve(f,`${t.name} answered YES. No penalty.`);const parent=f;physicalDraw(t,2,()=>{state.flow=parent;resolve(parent,`${t.name} did not answer YES and drew 2.`);});}
function tocQuestion(){const f=state.flow;if(!f||f.kind!=='truth_or_chaos'||f.step!=='question')return;const q=String($('#canonicalTocQuestion')?.value||'').trim(),opts=[...new Set(String($('#canonicalTocOptions')?.value||'YES,NO').split(',').map(x=>x.trim()).filter(Boolean))];if(q.length<5||opts.length<2||opts.length>4)return toast('Group question','Provide one question and 2-4 comparable answer choices.');f.question=q;f.options=opts;f.answers={};f.step='group-answer';render();autoBots();}
function tocAnswer(choice){const f=state.flow,h=human();if(!f||f.kind!=='truth_or_chaos'||f.step!=='group-answer'||!f.targetIds.includes(h.id)||f.answers[h.id]||!f.options.includes(choice))return;f.answers[h.id]=choice;finishTocAnswers(f);}
function finishTocAnswers(f){if(!f.targetIds.every(id=>f.answers[id]))return render();const vals=f.targetIds.map(id=>f.answers[id]);if(vals.every(v=>v===vals[0]))return resolve(f,`All group answers matched: ${vals[0]}. No group punishment.`);f.step='group-dare';event('TRUTH OR CHAOS','Answers differed. CHAOS triggers a whole-group Dare.');render();autoBots();}
function tocDare(){const f=state.flow,v=String($('#canonicalGroupDare')?.value||'').trim();if(!f||f.kind!=='truth_or_chaos'||f.step!=='group-dare'||v.length<5)return;f.groupDare=v;f.completions={};f.step='group-complete';render();autoBots();}
function tocComplete(){const f=state.flow,h=human();if(!f||f.kind!=='truth_or_chaos'||f.step!=='group-complete'||!f.targetIds.includes(h.id))return;f.completions[h.id]='DONE';finishGroup(f);}
function finishGroup(f){if(!f.targetIds.every(id=>f.completions[id]))return render();resolve(f,'The whole-group activity finished.');}
function machiavelli(choice){const f=state.flow,s=state.session;if(!f||f.kind!=='machiavelli'||f.step!=='choice')return;const zones=()=>[...s.players.flatMap(p=>p.hand),...s.deck,...s.discard];if(choice==='convert-weak')zones().forEach(c=>{if(c.kind==='skip'){c.kind='draw';c.symbol='draw';}});else if(choice==='taboo-all')s.players.forEach(p=>p.hand.push(generated('taboo')));else if(choice==='no-mercy'){s.players.forEach(p=>p.hand=p.hand.filter(c=>c.kind!=='nope'));s.deck=s.deck.filter(c=>c.kind!=='nope');s.discard=s.discard.filter(c=>c.kind!=='nope');}else if(choice==='paranoia-spreads')s.players.forEach((p,i)=>p.hand.push(generated(pick(['dig_me','paranoia'],`${s.seed}:spread:${state.revision}:${i}`))));else if(choice==='double-pressure'){const originals=s.deck.filter(c=>c.kind==='truth'||c.kind==='dare');s.deck.push(...originals.map(c=>generated(c.kind,{color:c.color,value:c.value})));s.deck=shuffle(s.deck,`${s.seed}:pressure:${state.revision}`);}else if(choice==='reverse-confession-all')s.players.forEach(p=>p.hand.push(generated('reverse_confession')));else return;const title=MACHIAVELLI.find(x=>x[0]===choice)?.[1]??choice;event('MACHIAVELLI',`${title} activated.`);resolve(f,`${title} was applied immediately.`);}
function confession(live=false){const f=state.flow;if(!f||f.kind!=='reverse_confession'||f.step!=='confess')return;const v=String($('#canonicalConfession')?.value||'').trim();if(!live&&!v)return;event('REVERSE CONFESSION',`${player(f.actorId).name} confessed${live?' live; content was not captured':''}.`);resolve(f,'Confession given. Whether it was real or made up remains undisclosed.');}
function digTarget(id){const f=state.flow;if(!f||f.kind!=='dig_me'||f.step!=='target'||id===f.actorId)return;f.targetId=id;f.step='dig-question';render();autoBots();}
function digQuestion(live=false){const f=state.flow;if(!f||f.kind!=='dig_me'||f.step!=='dig-question')return;const v=String($('#canonicalDig')?.value||'').trim();if(!live&&v.length<3)return;f.question=v;f.live=live;f.step='dig-answer';event('DIG ME',`${player(f.actorId).name} personally asked ${player(f.targetId).name} a question about themselves${live?' live; text was not captured':''}.`);render();autoBots();}
function digAnswered(){const f=state.flow;if(!f||f.kind!=='dig_me'||f.step!=='dig-answer')return;resolve(f,`${player(f.targetId).name} answered the DIG ME question.`);}
function activateGhost(){const p=current();if(!p?.isHuman||!p.ghostArmed||p.ghostTurns||state.flow)return;state.session.exhausted.push(p.ghostArmed);p.ghostArmed=null;p.ghostTurns=2;event('GHOST ACTIVATED',`${p.name} is a Ghost for two personal turns: no normal draw, legal plays only.`);render();}
function endGhost(){const p=current();if(!p?.isHuman||p.ghostTurns<=0||p.hand.some(c=>legal(c,p)))return;event('GHOST TURN',`${p.name} had no legal play and ended the Ghost turn without drawing.`);finishTurn(p);}

function autoBots(){clearTimeout(state.botTimer);const f=state.flow;if(!f)return;state.botTimer=setTimeout(()=>{if(state.flow!==f)return;const a=player(f.actorId);if(f.kind==='truth'){if(f.step==='source'&&!a.isHuman)return chooseSource('roulette');if(f.step==='preview'&&!player(f.targetId).isHuman)return publish();if(f.step==='response'&&!player(f.targetId).isHuman)return truthAnswer(true);}if(f.kind==='dare'){if(f.step==='target'&&!a.isHuman)return selectDareTarget(state.session.players.find(p=>p.id!==a.id).id);if(f.step==='source'&&!a.isHuman)return chooseSource('roulette');if(f.step==='preview'&&!player(f.targetId).isHuman)return publish();if(f.step==='response'&&!player(f.targetId).isHuman)return dareDone();}if(f.kind==='paranoia'){if(f.step==='source'&&!a.isHuman)return chooseSource('roulette');if(f.step==='preview'&&!a.isHuman)return publish();if(f.step==='paranoia-target'&&!a.isHuman)return paranoiaTarget(state.session.players.find(p=>p.id!==a.id).id);if(f.step==='paranoia-branch'&&!a.isHuman)return paranoiaBranch('classic');if(f.step==='paranoia-answer-player'&&!player(f.targetId).isHuman)return paranoiaAnswerPlayer(state.session.players.find(p=>p.id!==f.targetId).id);if(f.step==='paranoia-decision'&&!player(f.answerId).isHuman)return paranoiaDecision('keep',true);if(f.step==='paranoia-target-answer'&&!player(f.targetId).isHuman)return paranoiaAnswered();if(f.step==='paranoia-vote'){state.session.players.filter(p=>p.id!==f.targetId&&!p.isHuman&&!f.votes[p.id]).forEach(p=>f.votes[p.id]='BELIEVE');return finishParanoiaVote(f);}}if(f.kind==='duel'){if(f.step==='target'&&!a.isHuman)return duelTarget(state.session.players.find(p=>p.id!==a.id).id);if(f.step==='source'&&!a.isHuman)return chooseSource('roulette');if(f.step==='preview'&&!a.isHuman)return publish();if(f.step==='duel-timer'&&!a.isHuman)return duelTimer(30);if(f.step==='duel-challenger'&&!a.isHuman)return duelResponse('challenger');if(f.step==='duel-opponent'&&!player(f.opponentId).isHuman)return duelResponse('opponent');if(f.step==='duel-vote'){state.session.players.filter(p=>![f.actorId,f.opponentId].includes(p.id)&&!p.isHuman&&!f.votes[p.id]).forEach(p=>f.votes[p.id]=f.actorId);return finishDuelVote(f);}}if(f.kind==='chaos'&&f.step==='chaos'&&!a.isHuman)return chaosResolve();if(f.kind==='tag'&&f.step==='target'&&!a.isHuman)return tagTarget(state.session.players.find(p=>p.id!==a.id).id);if(f.kind==='hijack'&&f.step==='target'&&!a.isHuman)return hijackTarget(state.session.players.find(p=>p.id!==a.id).id);if(f.kind==='taboo'){if(f.step==='target'&&!a.isHuman)return tabooTarget(state.session.players.find(p=>p.id!==a.id).id);if(f.step==='taboo-question'&&!a.isHuman)return submitTabooQuestion('Do you agree that this table is complete chaos?');if(f.step==='taboo-answer'&&!player(f.targetId).isHuman)return tabooAnswer(true);}if(f.kind==='truth_or_chaos'){if(f.step==='question'&&!a.isHuman){f.question='Would you trust this group with your phone for five minutes?';f.options=['YES','NO'];f.answers={};f.step='group-answer';return autoBots();}if(f.step==='group-answer'){f.targetIds.filter(id=>!player(id).isHuman&&!f.answers[id]).forEach(id=>f.answers[id]=pick(f.options,`${state.session.seed}:toc:${state.revision}:${id}`));return finishTocAnswers(f);}if(f.step==='group-dare'&&!a.isHuman){f.groupDare='Everyone does a group dance for 20 seconds.';f.completions={};f.step='group-complete';return autoBots();}if(f.step==='group-complete'){f.targetIds.filter(id=>!player(id).isHuman).forEach(id=>f.completions[id]='DONE');return finishGroup(f);}}if(f.kind==='machiavelli'&&f.step==='choice'&&!a.isHuman)return machiavelli(pick(MACHIAVELLI,`${state.session.seed}:mach:${state.revision}`)[0]);if(f.kind==='reverse_confession'&&f.step==='resolved'&&!a.isHuman)return completeFlow();if(f.kind==='dig_me'){if(f.step==='target'&&!a.isHuman)return digTarget(state.session.players.find(p=>p.id!==a.id).id);if(f.step==='dig-question'&&!a.isHuman){f.live=true;f.step='dig-answer';return autoBots();}if(f.step==='dig-answer'&&!player(f.targetId).isHuman)return digAnswered();}},300);}
function scheduleBot(){clearTimeout(state.botTimer);const p=current();if(!state.session||state.flow||!p||p.isHuman||state.session.winnerId)return;state.botTimer=setTimeout(()=>{if(state.flow||current()?.id!==p.id)return;if(p.ghostArmed&&!p.ghostTurns&&pick([true,false],`${state.session.seed}:ghost:${state.revision}:${p.id}`)){state.session.exhausted.push(p.ghostArmed);p.ghostArmed=null;p.ghostTurns=2;}const card=p.hand.find(c=>legal(c,p));if(card)playCard(card.id);else if(p.ghostTurns>0)finishTurn(p);else drawTurn();},450);}
function tick(){const s=state.session;if(!state.active||!s||s.winnerId)return;const now=Date.now();if(state.flow?.deadline&&now>=state.flow.deadline){const f=state.flow;if(f.kind==='paranoia'&&f.step==='paranoia-decision')return paranoiaDecision('keep',false);if(f.kind==='paranoia'&&f.step==='paranoia-vote')return finishParanoiaVote(f);if(f.kind==='duel')return resolve(f,'Duel timed out. No winner or answer content was invented.');return resolve(f,'Interaction timed out safely. No answer content was invented.');}if(!state.flow&&s.deadline&&now>=s.deadline&&s.phase==='PLAY_DRAW'){event('TURN TIMEOUT',`${current().name} timed out; the turn advances.`);finishTurn(current());}renderTimer();}

function cardRule(k){return({number:'Match color or number.',skip:'Skip next player.',reverse:'Reverse direction.',draw:'Next player draws 2.',wild:'Choose active color.',truth:'Answer or Pass and Draw 2.',dare:'Choose another player, then challenge them.',paranoia:'Personal question: Classic or Stranger.',chaos:'Whole-table disruption.',duel:'Challenge one opponent.',nope:'Escape Truth or Dare.',tag:'Target gets a bonus Play-or-Draw action.',hijack:'Permanently swap rotation positions.',taboo:'Answer YES or Draw 2.',truth_or_chaos:'Group consensus or group Dare.',machiavelli:'Choose one of six fixed corruptions.',ghost:'Arm; no normal draw for two Ghost turns.',reverse_confession:'Confess; real or made up.',dig_me:'Ask another player a question about you.'})[k]??familyLabel(k);}
function renderCard(c,p){const ok=p?legal(c,p):false,title=familyLabel(c.kind),icon=c.kind==='number'?`<span class="game-card__icon is-number">${esc(c.value)}</span>`:`<span class="game-card__icon">${esc(title.slice(0,2).toUpperCase())}</span>`;return `<button class="game-card game-card--mini" data-canonical-card="true" data-action="play-card" data-card-id="${esc(c.id)}" data-kind="${esc(c.kind)}"${c.color?` data-color="${esc(c.color)}"`:''} data-legal="${ok}" aria-disabled="${!ok}" type="button"><strong class="game-card__title">${esc(title)}</strong>${icon}<p class="game-card__rule">${esc(cardRule(c.kind))}</p></button>`;}
function button(action,text,data='',cls=''){return `<button class="button ${cls}" data-canonical-action="${action}" ${data} type="button">${esc(text)}</button>`;}
function targetButtons(exclude=[]){return `<div class="target-grid">${state.session.players.filter(p=>!exclude.includes(p.id)).map(p=>`<button class="target-option" data-canonical-action="target" data-target-id="${p.id}" type="button"><span class="avatar">${esc(p.name[0])}</span><span><b>${esc(p.name)}</b><small style="display:block">${p.hand.length} cards</small></span></button>`).join('')}</div>`;}
function render(){const s=state.session;if(!state.active||!s)return;const h=human(),c=current();if($('#gameRoomName'))$('#gameRoomName').textContent=s.room;if($('#gameRoomMeta'))$('#gameRoomMeta').textContent=`${s.players.length} players - Canonical GameRules.md - Round ${s.round}`;if($('#currentTurnName'))$('#currentTurnName').textContent=c?.name??'-';if($('#activeColorLabel'))$('#activeColorLabel').textContent=COLOR_LABEL[s.activeColor]??s.activeColor??'-';if($('#activeSymbolLabel'))$('#activeSymbolLabel').textContent=String(s.activeSymbol??'-').toUpperCase();if($('#directionLabel'))$('#directionLabel').textContent=s.direction===1?'Clockwise':'Counterclockwise';if($('#boardPhaseLabel'))$('#boardPhaseLabel').textContent=s.phase.replaceAll('_',' / ');if($('#handCount'))$('#handCount').textContent=`${h.hand.length} card${h.hand.length===1?'':'s'}`;if($('#drawPileCount'))$('#drawPileCount').textContent=`${s.deck.length} left`;if($('#phoneRevision'))$('#phoneRevision').textContent=String(state.revision);const pl=$('#playerList');if(pl)pl.innerHTML=s.players.map(p=>`<div class="player-row${p.id===c.id?' is-current':''}${p.isHuman?' is-you':''}"><span class="avatar">${esc(p.name[0])}</span><span class="player-meta"><b>${esc(p.name)}</b><span>${p.ghostTurns?`Ghost - ${p.ghostTurns} left`:p.ghostArmed?'Ghost armed':'Active'}</span></span><strong class="card-count">${p.hand.length}</strong></div>`).join('');const hand=$('#handScroll');if(hand)hand.innerHTML=h.hand.map(x=>renderCard(x,h)).join('')||'<div class="empty-state"><h3>Empty hand</h3><p>Waiting for the authoritative resolution boundary.</p></div>';const d=$('#discardSlot');if(d){d.innerHTML=top()?renderCard(top(),null):'';d.querySelectorAll('[data-action="play-card"]').forEach(n=>{n.removeAttribute('data-action');n.disabled=true;});}const ev=$('#eventList');if(ev)ev.innerHTML=state.events.map(e=>`<article class="event-item"><div class="event-item__top"><b>${esc(e.type)}</b><time>${esc(e.time)}</time></div><p>${esc(e.message)}</p></article>`).join('');const canDraw=c?.isHuman&&!state.flow&&s.phase==='PLAY_DRAW'&&c.ghostTurns===0&&!c.hand.some(x=>legal(x,c));$$('[data-draw-control]').forEach(b=>b.disabled=!canDraw);renderPanel();renderFlow();renderTimer();}
function renderPanel(){const s=state.session,c=current(),title=$('#activeChallengeTitle'),copy=$('#activeChallengeCopy'),inline=$('#inlineFlowControls');if(!title||!copy)return;if(s.winnerId){title.textContent='Game over';copy.textContent=`${player(s.winnerId).name} legally emptied their hand.`;}else if(state.flow){title.textContent=`${familyLabel(state.flow.kind)} resolution`;copy.textContent=state.flow.prompt||state.flow.question||state.flow.effect?.copy||'Complete the active card effect.';}else{title.textContent=c.isHuman?'Play or draw':`${c.name}'s turn`;copy.textContent=c.ghostTurns?'Ghost turn: play a legal card. There is no normal draw.':'Match color or symbol, use a legal special, or draw when no legal card is held.';}if(inline){if(c?.isHuman&&!state.flow&&c.ghostArmed&&!c.ghostTurns)inline.innerHTML=button('activate-ghost','Activate Ghost','','button--primary');else if(c?.isHuman&&!state.flow&&c.ghostTurns&&!c.hand.some(x=>legal(x,c)))inline.innerHTML=button('end-ghost','End Ghost Turn - No Draw','','button--primary');else inline.innerHTML='';}}
function renderFlow(){const dialog=$('#flowDialog'),f=state.flow;if(!dialog)return;if(!f){if(dialog.open)dialog.close();return;}if(f.kind==='taboo'&&!needsHuman(f)){if(dialog.open)dialog.close();return;}if(f.kind!=='taboo'&&!needsHuman(f)&&!player(f.actorId)?.isHuman){if(dialog.open)dialog.close();return;}if($('#flowDialogTitle'))$('#flowDialogTitle').textContent=familyLabel(f.kind);if($('#flowDialogSubtitle'))$('#flowDialogSubtitle').textContent='GameRules.md is the gameplay authority.';const body=$('#flowDialogBody');let html='';if(f.resolved)html=`<div class="prompt-display"><h3>${esc(f.outcome)}</h3>${button('continue','Continue','','button--primary')}</div>`;else if(f.kind==='wild')html=`<div class="prompt-display"><h3>Choose active color</h3>${COLORS.map(x=>button('wild',COLOR_LABEL[x],`data-color="${x}"`)).join('')}</div>`;else if(['truth','dare','paranoia','duel'].includes(f.kind)&&f.step==='source')html=`<div class="prompt-display"><h3>Choose source</h3>${button('source','Write manually','data-source="manual"','button--primary')}${button('source','Use Roulette','data-source="roulette"')}</div>`;else if(['truth','dare','paranoia','duel'].includes(f.kind)&&f.step==='manual')html=`<div class="prompt-display"><textarea class="textarea" id="canonicalManual" minlength="10" maxlength="280"></textarea>${button('manual','Use this prompt','','button--primary')}</div>`;else if(['truth','dare'].includes(f.kind)&&f.step==='preview'){const t=player(f.targetId),has=t.hand.some(c=>c.kind==='nope');html=`<div class="private-banner"><b>Private preview for ${esc(t.name)}</b></div><div class="prompt-display"><h3>${esc(f.prompt)}</h3>${button('publish','Reveal to room','','button--primary')}${f.source==='roulette'&&t.rewind?button('rewind','Rewind'):''}${button('pass','Pass / Not for Me')}${has?button('nope','Play Nope','','button--gold'):''}</div>`;}else if(f.kind==='truth'&&f.step==='response'){const t=player(f.targetId),has=t.hand.some(c=>c.kind==='nope');html=`<div class="prompt-display"><h3>${esc(f.prompt)}</h3><textarea class="textarea" id="canonicalTruth"></textarea>${button('truth','Submit answer','','button--primary')}${button('truth-live','Answered Live')}${button('pass','Pass / Not for Me')}${has?button('nope','Play Nope','','button--gold'):''}</div>`;}else if(f.kind==='dare'&&f.step==='target')html=`<div class="prompt-display"><h3>Choose another player for the Dare</h3>${targetButtons([f.actorId])}</div>`;else if(f.kind==='dare'&&f.step==='response'){const t=player(f.targetId),has=t.hand.some(c=>c.kind==='nope');html=`<div class="prompt-display"><h3>${esc(f.prompt)}</h3><p>${esc(t.name)} must complete it or refuse.</p>${button('dare-done','Dare completed','','button--primary')}${button('pass','Pass / Not for Me')}${has?button('nope','Play Nope','','button--gold'):''}</div>`;}else if(f.kind==='paranoia'&&f.step==='preview')html=`<div class="prompt-display"><h3>${esc(f.prompt)}</h3><p>Personal Paranoia question selected.</p>${button('publish','Continue to private target','','button--primary')}${button('pass','Pass')}</div>`;else if(f.kind==='paranoia'&&f.step==='paranoia-target')html=`<div class="prompt-display"><h3>${esc(f.prompt)}</h3><p>Choose the initial target privately.</p>${targetButtons([f.actorId])}${button('pass','Pass')}</div>`;else if(f.kind==='paranoia'&&f.step==='paranoia-branch')html=`<div class="prompt-display"><h3>Classic or Stranger?</h3>${button('paranoia-branch','Classic','data-branch="classic"','button--primary')}${button('paranoia-branch','Stranger','data-branch="stranger"')}</div>`;else if(f.kind==='paranoia'&&f.step==='paranoia-answer-player')html=`<div class="prompt-display"><h3>${esc(player(f.targetId).name)}, choose the answer player</h3>${targetButtons([f.targetId])}</div>`;else if(f.kind==='paranoia'&&f.step==='paranoia-decision')html=`<div class="prompt-display"><h3>${esc(player(f.answerId).name)}, Reveal or Keep Secret?</h3><p>Explicit Keep Secret costs Draw 1.</p>${button('paranoia-decision','Reveal','data-choice="reveal"','button--primary')}${button('paranoia-decision','Keep Secret - Draw 1','data-choice="keep"')}</div>`;else if(f.kind==='paranoia'&&f.step==='paranoia-target-answer')html=`<div class="prompt-display"><h3>${esc(f.prompt)}</h3><p>${esc(player(f.targetId).name)} answers before the Stranger vote.</p>${button('paranoia-answered','Answered Live','','button--primary')}</div>`;else if(f.kind==='paranoia'&&f.step==='paranoia-vote'){const h=human(),can=h.id!==f.targetId&&!f.votes[h.id];html=`<div class="prompt-display"><h3>Do you believe ${esc(player(f.targetId).name)}?</h3>${can?button('paranoia-vote','Believe','data-vote="BELIEVE"','button--primary')+button('paranoia-vote','Lying / Holding Back','data-vote="LYING"'):'<p>Your vote is not required.</p>'}</div>`;}else if(f.kind==='duel'&&f.step==='target')html=`<div class="prompt-display"><h3>Choose an opponent</h3>${targetButtons([f.actorId])}</div>`;else if(f.kind==='duel'&&f.step==='preview')html=`<div class="prompt-display"><h3>${esc(f.prompt)}</h3>${button('publish','Lock shared question','','button--primary')}</div>`;else if(f.kind==='duel'&&f.step==='duel-timer')html=`<div class="prompt-display"><h3>${esc(f.prompt)}</h3><p>Challenger chooses the timer.</p>${[15,30,45].map(x=>button('duel-timer',`${x} seconds`,`data-seconds="${x}"`,x===30?'button--primary':'')).join('')}</div>`;else if(f.kind==='duel'&&f.step==='duel-challenger')html=`<div class="prompt-display"><h3>${esc(f.prompt)}</h3><p>${esc(player(f.actorId).name)} answers first.</p>${button('duel-response','Challenger answered','data-side="challenger"','button--primary')}</div>`;else if(f.kind==='duel'&&f.step==='duel-opponent')html=`<div class="prompt-display"><h3>${esc(f.prompt)}</h3><p>${esc(player(f.opponentId).name)} answers the SAME question.</p>${button('duel-response','Opponent answered','data-side="opponent"','button--primary')}</div>`;else if(f.kind==='duel'&&f.step==='duel-vote'){const h=human(),can=![f.actorId,f.opponentId].includes(h.id)&&!f.votes[h.id];html=`<div class="prompt-display"><h3>Group vote</h3>${can?button('duel-vote',player(f.actorId).name,`data-id="${f.actorId}"`,'button--primary')+button('duel-vote',player(f.opponentId).name,`data-id="${f.opponentId}"`):'<p>Duel participants cannot vote on their own result.</p>'}</div>`;}else if(f.kind==='chaos'&&f.step==='chaos')html=`<div class="prompt-display"><h3>${esc(f.effect.title)}</h3><p>${esc(f.effect.copy)}</p>${button('chaos','Resolve CHAOS','','button--primary')}</div>`;else if(f.kind==='tag'&&f.step==='target')html=`<div class="prompt-display"><h3>TAG ALONG</h3><p>Choose another player. They immediately receive one bonus Play-or-Draw action and keep their regular turn.</p>${targetButtons([f.actorId])}</div>`;else if(f.kind==='hijack'&&f.step==='target')html=`<div class="prompt-display"><h3>HIJACK</h3><p>Permanently swap rotation positions; target Draws 1 and immediately takes over this position.</p>${targetButtons([f.actorId])}</div>`;else if(f.kind==='taboo'&&f.step==='target')html=`<div class="prompt-display"><h3>TABOO</h3>${targetButtons([f.actorId])}</div>`;else if(f.kind==='taboo'&&f.step==='taboo-question')html=`<div class="prompt-display"><h3>Ask ${esc(player(f.targetId).name)} one question</h3><textarea class="textarea" id="canonicalTaboo"></textarea>${button('taboo-question','Ask question','','button--primary')}</div>`;else if(f.kind==='taboo'&&f.step==='taboo-answer')html=`<div class="prompt-display"><h3>${esc(f.question)}</h3><p>${esc(player(f.targetId).name)} must answer YES or Draw 2.</p>${button('taboo-answer','YES','data-yes="true"','button--primary')}${button('taboo-answer','Not for me - Draw 2','data-yes="false"')}</div>`;else if(f.kind==='truth_or_chaos'&&f.step==='question')html=`<div class="prompt-display"><h3>Truth or Chaos - group consensus</h3><textarea class="textarea" id="canonicalTocQuestion"></textarea><input class="input" id="canonicalTocOptions" value="YES,NO" placeholder="2-4 choices separated by commas">${button('toc-question','Ask group','','button--primary')}</div>`;else if(f.kind==='truth_or_chaos'&&f.step==='group-answer'){const h=human(),can=f.targetIds.includes(h.id)&&!f.answers[h.id];html=`<div class="prompt-display"><h3>${esc(f.question)}</h3><p>Answers stay sealed until everyone submits.</p>${can?f.options.map(x=>button('toc-answer',x,`data-choice="${esc(x)}"`)).join(''):'<p>Waiting for other answers.</p>'}</div>`;}else if(f.kind==='truth_or_chaos'&&f.step==='group-dare')html=`<div class="prompt-display"><h3>CHAOS - answers differed</h3><p>Order one whole-group activity.</p><textarea class="textarea" id="canonicalGroupDare"></textarea>${button('toc-dare','Set group Dare','','button--primary')}</div>`;else if(f.kind==='truth_or_chaos'&&f.step==='group-complete'){const h=human(),can=f.targetIds.includes(h.id)&&!f.completions[h.id];html=`<div class="prompt-display"><h3>${esc(f.groupDare)}</h3>${can?button('toc-complete','Completed','','button--primary')+button('pass','Pass / Not for Me'):'<p>Waiting for the group.</p>'}</div>`;}else if(f.kind==='machiavelli'&&f.step==='choice')html=`<div class="prompt-display"><h3>Choose one corruption</h3><div class="target-grid">${MACHIAVELLI.map(([id,t,c])=>`<button class="target-option" data-canonical-action="machiavelli" data-choice="${id}" type="button"><span><b>${esc(t)}</b><small style="display:block">${esc(c)}</small></span></button>`).join('')}</div></div>`;else if(f.kind==='reverse_confession'&&f.step==='confess')html=`<div class="prompt-display"><h3>Confess something about yourself</h3><p>It can be real or made up. Do not say which.</p><textarea class="textarea" id="canonicalConfession"></textarea>${button('confession','Submit confession','','button--primary')}${button('confession-live','Confessed Live')}</div>`;else if(f.kind==='dig_me'&&f.step==='target')html=`<div class="prompt-display"><h3>DIG ME</h3><p>Choose another player. You must personally ask them a question about yourself.</p>${targetButtons([f.actorId])}</div>`;else if(f.kind==='dig_me'&&f.step==='dig-question')html=`<div class="prompt-display"><h3>Ask ${esc(player(f.targetId).name)} a question about you</h3><p>No Roulette. No generated suggestion.</p><textarea class="textarea" id="canonicalDig"></textarea>${button('dig-question','Use written question','','button--primary')}${button('dig-live','Ask it Live')}</div>`;else if(f.kind==='dig_me'&&f.step==='dig-answer')html=`<div class="prompt-display"><h3>${f.live?'Live DIG ME question':esc(f.question)}</h3><p>${esc(player(f.targetId).name)} answers.</p>${button('dig-answered','Answered Live','','button--primary')}</div>`;body.innerHTML=html;if(!dialog.open)dialog.showModal();}
function renderTimer(){const d=state.flow?.deadline||state.session?.deadline,remaining=d?Math.max(0,Math.ceil((d-Date.now())/1000)):0;if($('#timerValue'))$('#timerValue').textContent=String(remaining);if($('#timerProgress'))$('#timerProgress').style.width=`${Math.max(0,Math.min(100,remaining/((state.flow?SOCIAL_MS:TURN_MS)/1000)*100))}%`;}
function targetAction(id){const f=state.flow;if(!f)return;if(f.kind==='dare')selectDareTarget(id);else if(f.kind==='paranoia'&&f.step==='paranoia-target')paranoiaTarget(id);else if(f.kind==='paranoia'&&f.step==='paranoia-answer-player')paranoiaAnswerPlayer(id);else if(f.kind==='duel')duelTarget(id);else if(f.kind==='tag')tagTarget(id);else if(f.kind==='hijack')hijackTarget(id);else if(f.kind==='taboo')tabooTarget(id);else if(f.kind==='dig_me')digTarget(id);}
function click(e){const b=e.target instanceof Element?e.target.closest('button,[data-nav],a'):null;if(!b)return;if(b.id==='startGameButton'){e.preventDefault();e.stopImmediatePropagation();startGame();return;}if(state.active&&b.matches('[data-nav="game"]')){e.preventDefault();e.stopImmediatePropagation();showGame();render();return;}if(!state.active)return;if(b.dataset.action==='play-card'&&b.dataset.canonicalCard==='true'){e.preventDefault();e.stopImmediatePropagation();playCard(b.dataset.cardId);return;}if(b.dataset.action==='draw-card'){e.preventDefault();e.stopImmediatePropagation();drawTurn();return;}if(['safety-pass','safety-rewind','use-nope'].includes(b.dataset.action)){e.preventDefault();e.stopImmediatePropagation();if(b.dataset.action==='safety-pass')pass();else if(b.dataset.action==='safety-rewind')rewind();else nope();return;}if(b.dataset.action==='flow-close-request'&&state.flow){e.preventDefault();e.stopImmediatePropagation();toast('Resolution required','Finish the active card effect first.');return;}const a=b.dataset.canonicalAction;if(!a)return;e.preventDefault();e.stopImmediatePropagation();if(a==='continue')completeFlow();else if(a==='wild'){state.session.activeColor=b.dataset.color;state.session.activeSymbol='wild';resolve(state.flow,`Active color changed to ${COLOR_LABEL[b.dataset.color]}.`);}else if(a==='source')chooseSource(b.dataset.source);else if(a==='manual')manualPrompt($('#canonicalManual')?.value);else if(a==='target')targetAction(b.dataset.targetId);else if(a==='publish')publish();else if(a==='rewind')rewind();else if(a==='pass')pass();else if(a==='nope')nope();else if(a==='truth')truthAnswer(false);else if(a==='truth-live')truthAnswer(true);else if(a==='dare-done')dareDone();else if(a==='paranoia-branch')paranoiaBranch(b.dataset.branch);else if(a==='paranoia-decision')paranoiaDecision(b.dataset.choice,true);else if(a==='paranoia-answered')paranoiaAnswered();else if(a==='paranoia-vote')paranoiaVote(b.dataset.vote);else if(a==='duel-timer')duelTimer(b.dataset.seconds);else if(a==='duel-response')duelResponse(b.dataset.side);else if(a==='duel-vote')duelVote(b.dataset.id);else if(a==='chaos')chaosResolve();else if(a==='taboo-question')tabooQuestion();else if(a==='taboo-answer')tabooAnswer(b.dataset.yes==='true');else if(a==='toc-question')tocQuestion();else if(a==='toc-answer')tocAnswer(b.dataset.choice);else if(a==='toc-dare')tocDare();else if(a==='toc-complete')tocComplete();else if(a==='machiavelli')machiavelli(b.dataset.choice);else if(a==='confession')confession(false);else if(a==='confession-live')confession(true);else if(a==='dig-question')digQuestion(false);else if(a==='dig-live')digQuestion(true);else if(a==='dig-answered')digAnswered();else if(a==='activate-ghost')activateGhost();else if(a==='end-ghost')endGhost();}

export function initializeCanonicalGameRuntime(){document.addEventListener('click',click,true);state.tick=window.setInterval(tick,250);window.__CRIBBIT_CANONICAL_GAME__={state,startGame,render};}
